  $('#tabs').innerHTML=ordered.map(t=>`<div class="tab ${t.id===S.activeTabId?'active':''}" data-tab-id="${E(t.id)}" role="tab" tabindex="0" aria-selected="${t.id===S.activeTabId}" draggable="true" title="${E(t.title||'New tab')}\n${E(t.url||'')}"><span class="tab-icon">${tabIcon(t)}</span><span class="tab-text">${E(t.title||'New tab')}</span>${t.pinned?'<span class="tab-pin">⌁</span>':''}${t.audible?`<button class="icon-button tiny" data-action="mute" data-id="${E(t.id)}" title="${t.muted?'Unmute':'Mute'} tab">${icon(t.muted?'mute':'volume')}</button>`:''}<button class="tab-close" data-action="close-tab" data-id="${E(t.id)}" title="Close tab" aria-label="Close ${E(t.title||'tab')}">×</button>${S.agents.some(a=>(a.tabs||[]).includes(t.id))?'<i class="tab-agent"></i>':''}</div>`).join('');
  if(!ordered.length)$('#tabs').innerHTML='<div class="empty-tabs"><p style="font-size:10px;color:var(--soft);text-align:center;line-height:1.8;padding:15px 8px">A fresh space.<br>Open a tab to begin.</p></div>';
