function settingsPage() {return `<section class="internal-page">${pageHeader(['settings','Make it yours'],'A space that feels like you.','Thoughtful defaults. Just enough control.')}<div class="section-card"><h2>Look & feel</h2>${settingRow('Appearance','Follow your Mac, or choose your own atmosphere.',`<div class="segmented">${['system','light','dark'].map(t=>`<button class="${(S.settings.theme||'system')===t?'active':''}" data-action="theme" data-value="${t}">${t.charAt(0).toUpperCase()+t.slice(1)}</button>`).join('')}</div>`)}${settingRow('Compact sidebar','Keep your tabs close and your page in focus.',switchButton('sidebarCollapsed',S.settings.sidebarCollapsed,'Compact sidebar'))}${settingRow('Search engine','Choose where your curiosity starts.',`<select id="search-engine" aria-label="Search engine" data-setting="searchEngine"><option value="brave" ${S.settings.searchEngine==='brave'?'selected':''}>Brave Search</option><option value="duckduckgo" ${S.settings.searchEngine==='duckduckgo'?'selected':''}>DuckDuckGo</option><option value="google" ${S.settings.searchEngine==='google'?'selected':''}>Google</option></select>`)}</div><div class="section-card"><h2>Tabs & movement</h2>${settingRow('Restore your session','Pick up where you left off. Private tabs stay private.',switchButton('restoreSession',S.settings.restoreSession!==false,'Restore your session'))}${settingRow('Keep Mission Control tidy','Tab cards flow into the next page as your space grows.',switchButton('autoTidy',S.settings.autoTidy!==false,'Keep Mission Control tidy'))}</div><div class="section-card"><h2>Privacy & protection</h2>${settingRow('Block ads & trackers',S.shields.status==='ready'?'Network filters and cosmetic filtering protect every normal and private tab.':S.shields.status==='loading'?'Loading protection. Open the shield for details.':'Protection is unavailable. No filtering is active.',`<button class="switch ${S.shields.enabled!==false?'on':''}" role="switch" aria-checked="${S.shields.enabled!==false}" aria-label="Block ads and trackers" data-action="shield-toggle"></button>`)}<div class="privacy-row">${number(S.shields.filterCount)} filtering rules · ${number(S.shields.blocked)} requests blocked<br>Protection reduces ads and tracking. It does not guarantee that every ad will be removed or reproduce all Brave Shields features.</div></div><div class="section-card"><h2>Your spaces <button class="button" data-action="workspace-new" style="float:right;margin-top:-6px;padding:5px 9px">＋ New space</button></h2>${S.workspaces.map(w=>`<div class="setting-row workspace-setting" style="--space-color:${cssColor(w.color)}"><i class="space-dot"></i><button class="workspace-name" data-action="workspace" data-id="${E(w.id)}" style="background:transparent;text-align:left;padding:0">${E(w.name)}</button><button class="icon-button" data-action="workspace-rename" data-id="${E(w.id)}" title="Rename space" aria-label="Rename ${E(w.name)}">${icon('edit')}</button>${w.id!==S.workspaces[0]?.id?`<button class="icon-button" data-action="workspace-delete" data-id="${E(w.id)}" title="Remove space" aria-label="Remove ${E(w.name)}">${icon('trash')}</button>`:''}</div>`).join('')}</div><div class="section-card"><h2>A few useful shortcuts</h2>${[['New tab','⌘ T'],['Address bar','⌘ L'],['Command palette','⌘ K'],['Mission Control','⌘ ⇧ M'],['Reopen closed tab','⌘ ⇧ T'],['Bookmark page','⌘ D']].map(([a,b])=>`<div class="shortcut-line"><span>${a}</span><kbd>${b}</kbd></div>`).join('')}</div><p class="info-note">Aster · A personal Chromium browser, with a native macOS window and a shared local automation interface.</p></section>`;}
