function listFilter(placeholder) {return `<label class="list-filter">${icon('search')}<input id="page-filter" placeholder="${E(placeholder)}" aria-label="${E(placeholder)}" value="${E(pageQuery)}"></label>`;}
function historyPage() {const items=S.history.filter(t=>(t.title+' '+t.url).toLowerCase().includes(pageQuery.toLowerCase())).slice(0,300);return `<section class="internal-page">${pageHeader(['history','Your footsteps'],'A little way back.','Find the pages you have visited. Private tabs never appear here.',S.history.length?'<button class="button danger" data-action="history-clear">Clear history</button>':'')}${S.history.length?listFilter('Search your history'):''}${items.length?`<div class="section-card">${items.map(t=>`<div class="list-row"><button class="list-open" data-action="open" data-url="${E(t.url)}"><span class="list-leading">${E(initial(host(t.url)))}</span><span class="list-copy"><strong>${E(t.title||host(t.url))}</strong><small>${E(t.url)}</small></span></button><span class="time">${relative(t.visitedAt)}</span></div>`).join('')}</div>`:emptyState('history',pageQuery?'No pages found':'Your next adventure starts here.',pageQuery?'Try another search.':'The places you explore will appear here, ready to revisit.','<button class="button" data-action="new">Open a new tab</button>')}</section>`;}
function bookmarksPage() {const items=S.bookmarks.filter(t=>(t.title+' '+t.url).toLowerCase().includes(pageQuery.toLowerCase()));return `<section class="internal-page">${pageHeader(['bookmark','Worth keeping'],'Good things, saved.','A small collection of places you want to come back to.','<button class="button primary" data-action="favorite-add">＋ Add bookmark</button>')}${S.bookmarks.length?listFilter('Search your bookmarks'):''}${items.length?`<div class="section-card">${items.map(t=>`<div class="list-row"><button class="list-open" data-action="open" data-url="${E(t.url)}"><span class="list-leading" style="color:${agentColor(t.url)}">${E(initial(t.title||host(t.url)))}</span><span class="list-copy"><strong>${E(t.title||host(t.url))}</strong><small>${E(t.url)}</small></span></button><button class="icon-button" data-action="bookmark-remove" data-url="${E(t.url)}" title="Remove bookmark" aria-label="Remove ${E(t.title)}">${icon('close')}</button></div>`).join('')}</div>`:emptyState('bookmark',pageQuery?'Nothing by that name.':'Keep a little inspiration.',pageQuery?'Try another search.':'Save any page with ⌘D, or add a favorite to your new tab page.')}</section>`;}
function downloadsPage() {return `<section class="internal-page">${pageHeader(['download','Brought home'],'Your little collection.','Files you download from the web, all in one place.')}${S.downloads.length?`<div class="section-card">${S.downloads.map(d=>`<div class="list-row"><span class="list-leading">${icon('download')}</span><span class="list-copy"><strong>${E(d.name||'Download')}</strong><small>${E(d.state||'in progress')} · ${bytes(d.received)}${d.total?' of '+bytes(d.total):''}</small>${d.state==='progressing'?`<span class="progress-track"><i style="width:${Math.min(100,Math.max(0,((d.received||0)/(d.total||1))*100))}%"></i></span>`:''}</span>${d.state==='completed'?`<button class="button" data-action="download-open" data-id="${E(d.id)}">Open</button><button class="icon-button" data-action="download-reveal" data-id="${E(d.id)}" title="Show in Finder" aria-label="Show ${E(d.name)} in Finder">${icon('folder')}</button>`:''}</div>`).join('')}</div>`:emptyState('download','A clean slate.','Your downloads will appear here as you collect things from the web.')}</section>`;}
function codeBlock(code,id) {return `<div class="connection-code"><code>${E(code)}</code><button class="copy-code" data-action="copy-code" data-code-id="${E(id)}" title="Copy" aria-label="Copy command">${icon('copy')}</button></div>`;}
const connectionCodes = {};
function agentsPage() {const automation=S.automation||{};const mcp=automation.mcpPath||'path/to/Aster/bin/mcp.mjs';const cli=automation.cliPath||'path/to/Aster/bin/aster.mjs';connectionCodes.mcp=JSON.stringify({mcpServers:{aster:{command:'node',args:[mcp]}}},null,2);connectionCodes.cli=`node ${shellQuote(cli)} tabs.list\nnode ${shellQuote(cli)} tabs.create ${shellQuote(JSON.stringify({url:'https://example.com'}))}\nnode ${shellQuote(cli)} --agent Researcher session`;connectionCodes.api=`${automation.endpoint||'http://127.0.0.1:4318'}\nToken file: ${automation.tokenPath||'Available when the automation server starts'}`;return `<section class="internal-page">${pageHeader(['team','Shared curiosity'],'One browser. Many minds.','Bring your favorite agents into the same browser. You stay in the loop.')}<div class="agent-hero"><div class="agent-hero-top"><i class="live-dot"></i><strong>${S.agents.length?`${S.agents.length} agent${S.agents.length===1?'':'s'} connected`:'Ready for your first connection'}</strong></div><h2>A common space for your whole team.</h2><p>Connect multiple harnesses to one live session. Agents can open, inspect, and work in tabs together. Their activity appears here as it happens.</p><div class="protocol-tags"><span>MCP</span><span>CLI</span><span>LOCAL API</span><span>SHARED TABS</span></div></div>${S.agents.length?`<div class="section-card"><h2>Connected agents <span class="inline-count">${S.agents.length}</span></h2>${S.agents.map(a=>`<div class="list-row"><span class="agent-avatar" style="--agent-color:${agentColor(a.id)}">${E(initial(a.name))}</span><span class="list-copy"><strong>${E(a.name||a.id)}</strong><small>${E(a.transport||'Local API')} · ${(a.tabs||[]).length} active tab${(a.tabs||[]).length===1?'':'s'}</small></span><span class="time">${relative(a.lastSeen||a.connectedAt)}</span></div>`).join('')}</div>`:''}<div class="two-column"><div class="section-card"><h2>Connect with MCP</h2><p class="card-description">Add this server to any MCP-compatible agent. Restart that client to establish its connection.</p>${codeBlock(connectionCodes.mcp,'mcp')}<div style="padding:0 19px 18px"><button class="button" data-action="copy-code" data-code-id="mcp">${icon('copy')} Copy configuration</button></div></div><div class="section-card"><h2>Use your terminal</h2><p class="card-description">Open tabs and inspect your shared session from a script, a CLI, or your own harness.</p>${codeBlock(connectionCodes.cli,'cli')}<div style="padding:0 19px 18px"><button class="button" data-action="copy-code" data-code-id="cli">${icon('copy')} Copy commands</button></div></div></div><div class="section-card"><h2>Local connection</h2><p class="card-description">The interface listens on this Mac only. Connected agents can control your browser tabs. Only share the local token with harnesses you trust.</p>${codeBlock(connectionCodes.api,'api')}<div style="padding:0 19px 18px"><button class="button" data-action="open-path" data-kind="token">${icon('folder')} Show token file</button></div></div><div class="section-card"><h2>Live activity</h2>${S.activity.length?S.activity.slice(0,30).map(a=>`<div class="list-row activity-row"><i class="activity-dot" style="background:${agentColor(a.agentId)}"></i><span class="list-copy"><strong>${E(a.agentName||'Agent')} <span style="color:var(--muted);font-weight:400">${E(a.action||'used the browser')}</span></strong></span><span class="time">${relative(a.at)}</span></div>`).join(''):'<p class="card-description" style="padding-bottom:20px">A quiet room, for now. Agent actions will appear here when a harness connects.</p>'}</div></section>`;}
function errorPage(tab) {
  const reason = typeof tab.error === 'object' ? tab.error.description || tab.error.code : tab.error;
  const stopped = String(reason || '').startsWith('Page stopped:');
  return `<section class="error-page"><span class="empty-icon">${icon(stopped ? 'warning' : 'globe')}</span><h1>${stopped ? 'This tab stopped.' : 'This page could not load.'}</h1><p>${stopped ? 'Your browser and other tabs are still available. Reload this tab to continue.' : `We couldn't reach ${E(host(tab.url) || 'this page')}. Check your connection, or try again.`}</p><span class="error-code">${E(reason)}</span><button class="button primary" data-action="reload">${icon('reload')} Reload page</button></section>`;
}
function missionTabs() {return S.tabs.filter(t=>(missionWorkspace==='all'||t.workspace===missionWorkspace)&&(t.title+' '+t.url).toLowerCase().includes(missionQuery.toLowerCase()));}
function missionGeometry() {const width=innerWidth-(S.settings.sidebarCollapsed?76:246)-84;const columns=Math.max(2,Math.min(4,Math.floor(width/245)));const height=innerHeight-330;const rows=height>200?2:1;return {columns,capacity:S.settings.autoTidy===false?Math.max(8,S.tabs.length+1):Math.min(8,columns*rows)};}
function renderMission() {const {columns,capacity}=missionGeometry();const tabs=missionTabs(),pages=Math.max(1,Math.ceil((tabs.length+1)/capacity));missionPage=Math.max(0,Math.min(missionPage,pages-1));const start=missionPage*capacity,subset=tabs.slice(start,start+capacity);let cards=subset.map((t,i)=>{const w=S.workspaces.find(w=>w.id===t.workspace);const preview=t.thumbnail&&!t.url?.startsWith('aster://')?`<img src="${E(t.thumbnail)}" alt="Preview of ${E(t.title||'tab')}">`:t.url?.startsWith('aster://newtab')?'<div class="mission-mini-bar"><i></i><i></i><i></i></div><div class="mission-newtab"><div class="mini-orb"></div><strong>Room to explore.</strong></div>':`<div class="mission-fallback"><span>${t.url?.startsWith('aster://')?'✳':E(initial(host(t.url)))}</span>${E(host(t.url)||t.title||'New tab')}</div>`;return `<article class="mission-card ${t.id===S.activeTabId?'active':''}" data-mission-tab="${E(t.id)}" tabindex="0" role="button" aria-label="Open ${E(t.title||'tab')}" draggable="true" style="animation-delay:${i*25}ms"><button class="mission-close" data-action="close-tab" data-id="${E(t.id)}" aria-label="Close ${E(t.title||'tab')}" title="Close tab">×</button><div class="mission-preview">${preview}</div><div class="mission-card-meta"><i class="space-dot" style="--space-color:${cssColor(w?.color)}"></i><strong>${E(t.title||'New tab')}</strong>${t.private?icon('private','style="width:11px;height:11px;color:#a68cbe"'):''}</div></article>`;}).join('');if(start+subset.length===tabs.length&&subset.length<capacity)cards+='<button class="mission-new" data-action="mission-new"><span>＋</span>Open a new tab</button>';
  const queryFocus=document.activeElement?.id==='mission-filter';const selection=queryFocus?[$('#mission-filter').selectionStart,$('#mission-filter').selectionEnd]:null;
  $('#mission').innerHTML=`<div class="mission-header"><div><div class="mission-eyebrow">A little perspective</div><h1>Everything, in its place.</h1><p>${tabs.length} tab${tabs.length===1?'':'s'} · Drag to rearrange. Drop on a space to move.</p></div><button class="icon-button" data-action="mission-close" title="Close Mission Control · Esc" aria-label="Close Mission Control">${icon('close')}</button></div><div class="mission-spacebar"><button class="mission-space ${missionWorkspace==='all'?'active':''}" data-action="mission-space" data-id="all">All spaces <span style="opacity:.5">${S.tabs.length}</span></button>${S.workspaces.map(w=>`<button class="mission-space ${missionWorkspace===w.id?'active':''}" data-action="mission-space" data-id="${E(w.id)}" data-drop-workspace="${E(w.id)}"><i class="space-dot" style="--space-color:${cssColor(w.color)}"></i>${E(w.name)}</button>`).join('')}<label class="mission-search">${icon('search')}<input id="mission-filter" placeholder="Find a tab…" aria-label="Find a tab" value="${E(missionQuery)}"></label></div><div class="mission-grid" style="--mission-columns:${columns}">${cards}</div><div class="mission-footer"><span>${S.settings.autoTidy!==false?'Your tabs flow. Your space stays clear.':'Drag cards to make this space your own.'}</span><div class="mission-page-control"><button data-action="mission-prev" ${missionPage===0?'disabled':''} title="Previous page" aria-label="Previous page">${icon('back')}</button><div class="mission-page-dots">${Array.from({length:pages},(_,i)=>`<button class="${i===missionPage?'active':''}" data-action="mission-page" data-page="${i}" aria-label="Page ${i+1}"></button>`).join('')}</div><button data-action="mission-next" ${missionPage>=pages-1?'disabled':''} title="Next page" aria-label="Next page">${icon('forward')}</button><span>${missionPage+1} / ${pages}</span></div><span>Press <kbd>esc</kbd> to return</span></div>`;$('#mission').classList.remove('hidden');if(queryFocus){$('#mission-filter').focus();$('#mission-filter').setSelectionRange(...selection);}}
async function openMission() {dismissTransientUI();await syncOverlay();missionPage=0;missionQuery='';await invoke('ui:mission',{open:true});}
async function closeMission() {await invoke('ui:mission',{open:false});}
async function closeFloating() {$('#floating').classList.add('hidden');if(!floating)return;transientGeneration++;floating=null;await syncOverlay();}
async function openFloating(type) {if(floating===type)return closeFloating();const request=await beginTransient(type);if(request===null)return;if(type==='shields')renderShields();else renderMenu();$('#floating').classList.remove('hidden');}
function renderShields() {$('#floating').innerHTML=`<div class="shield-popover"><div class="shield-title"><span>${icon('shield')}</span><div><h2>A little peace of mind.</h2><small>${S.shields.enabled===false?'Protection paused':'Aster protection'}</small></div><button class="switch ${S.shields.enabled!==false?'on':''}" data-action="shield-toggle" role="switch" aria-checked="${S.shields.enabled!==false}" aria-label="Toggle protection"></button></div><div class="shield-stats"><strong>${number(S.shields.blocked)}</strong><span>ads & tracking requests blocked</span></div><div class="shield-detail"><span>Filtering engine</span><strong>${S.shields.status==='ready'?'Ready':S.shields.status==='loading'?'Loading filters':'Unavailable'}</strong></div><div class="shield-detail"><span>Rules available</span><strong>${number(S.shields.filterCount)}</strong></div><div class="shield-detail"><span>This tab</span><strong>${number(activeTab()?.blocked)} blocked</strong></div><p class="info-note">${S.shields.status==='ready'?'Filtering helps keep distractions and trackers away. Some ads may still appear. Protection is shared across all tabs.':S.shields.status==='loading'?'Filter protection is loading. Blocking starts when the engine is ready.':'The filtering engine is unavailable. Ads and tracking requests are not being filtered.'}</p><button class="menu-item" style="margin-top:8px" data-action="route" data-route="settings">${icon('settings')} Privacy settings ${icon('arrow')}</button></div>`;}
function renderMenu() {const items=[['new','plus','New tab','⌘T'],['private','private','New private tab','⌘⇧N'],['restore','history','Reopen closed tab','⌘⇧T'],null,['mission','grid','Mission Control','⌘⇧M'],['palette','search','Search tabs & commands','⌘K'],null,['route','bookmark','Bookmarks','', 'bookmarks'],['route','history','History','⌘Y','history'],['route','download','Downloads','','downloads'],['route','team','Agent connections','','agents'],null,['route','settings','Settings','⌘,','settings']];$('#floating').innerHTML=items.map(i=>i?`<button class="menu-item" data-action="${i[0]}" ${i[4]?`data-route="${i[4]}"`:''}>${icon(i[1])}${E(i[2])}<kbd>${E(i[3])}</kbd></button>`:'<div class="menu-divider"></div>').join('');}
async function openPalette() {const request=await beginTransient('palette');if(request===null)return;paletteIndex=0;$('#palette').classList.remove('hidden');$('#palette-input').value='';renderPalette();await invoke('ui:focus-chrome');if(request===transientGeneration&&paletteOpen)$('#palette-input').focus();}
async function closePalette() {$('#palette').classList.add('hidden');if(!paletteOpen)return;transientGeneration++;paletteOpen=false;await syncOverlay();}
function renderPalette() {const query=$('#palette-input').value.toLowerCase().trim();const commands=[{title:'Open a new tab',subtitle:'A fresh space for your next idea',icon:'plus',action:'new'},{title:'Mission Control',subtitle:'See all your tabs at a glance',icon:'grid',action:'mission'},{title:'Connect an agent',subtitle:'Bring your harness into Aster',icon:'team',action:'route',route:'agents'},{title:'Settings',subtitle:'Make Aster feel like you',icon:'settings',action:'route',route:'settings'},{title:'Bookmarks',subtitle:'Your saved little collection',icon:'bookmark',action:'route',route:'bookmarks'},{title:'History',subtitle:'Find your way back',icon:'history',action:'route',route:'history'},{title:'Downloads',subtitle:'Things you brought home',icon:'download',action:'route',route:'downloads'},{title:'New private tab',subtitle:'Explore without saving browsing history',icon:'private',action:'private'}];paletteItems=[...S.tabs.filter(t=>(t.title+' '+t.url).toLowerCase().includes(query)).slice(0,6).map(t=>({title:t.title||'New tab',subtitle:t.url,tab:t.id,icon:t.private?'private':'globe'})),...commands.filter(c=>(c.title+' '+c.subtitle).toLowerCase().includes(query))];if(query)paletteItems.push({title:`Search or go to “${$('#palette-input').value}”`,subtitle:'Open in the current tab',icon:'search',url:$('#palette-input').value});paletteIndex=Math.min(paletteIndex,Math.max(0,paletteItems.length-1));$('#palette-results').innerHTML='<div class="palette-category">'+(query?'Matches':'Your tabs & quick actions')+'</div>'+paletteItems.map((item,i)=>`<button class="palette-item ${i===paletteIndex?'active':''}" data-action="palette-select" data-index="${i}"><span>${icon(item.icon)}</span><div><strong>${E(item.title)}</strong><small>${E(item.subtitle)}</small></div>${i===paletteIndex?'<kbd>↵</kbd>':''}</button>`).join('');}
async function selectPalette(index) {const item=paletteItems[index];if(!item)return;await closePalette();if(item.tab){await invoke('tab:activate',{id:item.tab});if(S.missionOpen)await closeMission();}else if(item.url)await go(item.url);else await action(item.action,{route:item.route});}
async function openDialog(type,id) {const request=await beginTransient('dialog');if(request===null)return;const workspace=S.workspaces.find(w=>w.id===id);const contents=type==='favorite'?`<h2>Save a little inspiration.</h2><p>Add a favorite to your bookmarks and new tab page.</p><input id="dialog-title" placeholder="Name" aria-label="Bookmark name" required><input id="dialog-url" placeholder="https://example.com" aria-label="Bookmark URL" required>`:type==='workspace-delete'?`<h2>A little less space?</h2><p>Remove “${E(workspace?.name)}”? Its tabs will move to your first space.</p>`:type==='history-clear'?'<h2>A fresh start.</h2><p>Clear your browsing history? Bookmarks and downloaded files stay where they are.</p>':`<h2>${type==='workspace-rename'?'Rename your space.':'Make room for something.'}</h2><p>${type==='workspace-rename'?'A little name for the things you are working on.':'Keep a project, a purpose, or a passion in its own space.'}</p><input id="dialog-name" placeholder="Name your space" aria-label="Space name" value="${E(workspace?.name||'')}" required maxlength="30">`;$('#dialog').innerHTML=`<form class="dialog" id="dialog-form" data-type="${type}" data-id="${E(id||'')}">${contents}<div class="dialog-actions"><button type="button" class="button" data-action="dialog-close">Cancel</button><button class="button primary" type="submit">${type==='workspace-delete'?'Remove space':type==='history-clear'?'Clear history':type==='favorite'?'Add favorite':type==='workspace-rename'?'Save':'Create space'}</button></div></form>`;$('#dialog').classList.remove('hidden');await invoke('ui:focus-chrome');if(request!==transientGeneration||!dialogOpen)return;$('#dialog h2')?.setAttribute('id','dialog-heading');$('#dialog').setAttribute('aria-labelledby','dialog-heading');if(!$('#dialog').contains(document.activeElement))$('#dialog input, #dialog button')?.focus();}
async function closeDialog(){$('#dialog').classList.add('hidden');if(!dialogOpen)return;transientGeneration++;dialogOpen=false;await syncOverlay();}
async function action(name,data={}) {switch(name){case'new':await closeFloating();await invoke('tab:new',{});break;case'private':await closeFloating();await invoke('tab:new',{private:true});break;case'restore':await closeFloating();await invoke('tab:restore',{});break;case'sidebar':{const sidebarCollapsed=!S.settings.sidebarCollapsed;S.settings.sidebarCollapsed=sidebarCollapsed;setTheme();renderToolbar();await invoke('settings:update',{sidebarCollapsed});break;}case'workspace':pageQuery='';await invoke('workspace:activate',{id:data.id});break;case'workspace-new':await openDialog('workspace-new');break;case'workspace-rename':await openDialog('workspace-rename',data.id);break;case'workspace-delete':await openDialog('workspace-delete',data.id);break;case'close-tab':await invoke('tab:close',{id:data.id});break;case'mute':await invoke('tab:mute',{id:data.id});break;case'back':await invoke('tab:back',{});break;case'forward':await invoke('tab:forward',{});break;case'reload':await invoke('tab:reload',{});break;case'bookmark':await invoke('bookmark:toggle',{});break;case'bookmark-remove':await invoke('bookmark:toggle',{url:data.url});break;case'route':pageQuery='';await go('aster://'+data.route);break;case'open':await go(data.url);break;case'mission':S.missionOpen?await closeMission():await openMission();break;case'mission-close':await closeMission();break;case'mission-new':await invoke('tab:new',{});await closeMission();break;case'mission-space':missionWorkspace=data.id;missionPage=0;renderMission();break;case'mission-prev':missionPage--;renderMission();break;case'mission-next':missionPage++;renderMission();break;case'mission-page':missionPage=Number(data.page);renderMission();break;case'shields':await openFloating('shields');break;case'shield-toggle':await invoke('shields:toggle',{});break;case'menu':await openFloating('menu');break;case'palette':await openPalette();break;case'palette-select':await selectPalette(Number(data.index));break;case'theme':await invoke('settings:update',{theme:data.value});break;case'setting-toggle':{const value=!S.settings[data.setting];S.settings[data.setting]=value;await invoke('settings:update',{[data.setting]:value});break;}case'favorite-add':await openDialog('favorite');break;case'dialog-close':await closeDialog();break;case'history-clear':await openDialog('history-clear');break;case'download-open':await invoke('download:open',{id:data.id});break;case'download-reveal':await invoke('download:reveal',{id:data.id});break;case'copy-code':await invoke('clipboard:write',{text:connectionCodes[data.codeId]||''});toast('Copied. Ready for your next connection.');break;case'open-path':await invoke('app:open-path',{kind:data.kind});break;}}
document.addEventListener('click',async event=>{const actionEl=event.target.closest('[data-action]');if(floating&&!event.target.closest('#floating')&&!['menu','shields'].includes(actionEl?.dataset.action))await closeFloating();if(floating==='tabmenu'&&actionEl)await closeFloating();if(actionEl){event.preventDefault();event.stopPropagation();await action(actionEl.dataset.action,actionEl.dataset);return;}const tab=event.target.closest('[data-tab-id]');if(tab){await invoke('tab:activate',{id:tab.dataset.tabId});return;}const card=event.target.closest('[data-mission-tab]');if(card){await invoke('tab:activate',{id:card.dataset.missionTab});await closeMission();return;}if(event.target===$('#palette'))await closePalette();else if(event.target===$('#dialog'))await closeDialog();else if(floating&&!event.target.closest('#floating'))await closeFloating();});
document.addEventListener('submit',async event=>{event.preventDefault();if(event.target.id==='address-form'){const value=$('#address').value.trim();if(value){$('#address').blur();await go(value);}}else if(event.target.id==='home-search-form'){const value=$('#home-search').value.trim();if(value)await go(value);}else if(event.target.id==='palette-form')await selectPalette(paletteIndex);else if(event.target.id==='dialog-form'){const type=event.target.dataset.type,id=event.target.dataset.id;if(type==='favorite'){let url=$('#dialog-url').value.trim();const title=$('#dialog-title').value.trim();if(url&&title){if(!/^https?:\/\//i.test(url))url='https://'+url;try{const parsed=new URL(url);if(!['https:','http:'].includes(parsed.protocol))throw new Error('scheme');url=parsed.href;}catch{toast('Enter a valid web address.');return;}await invoke('bookmark:toggle',{url,title});await closeDialog();toast('Saved to your favorites.');}}else if(type==='history-clear'){await invoke('history:clear',{});await closeDialog();}else if(type==='workspace-delete'){await invoke('workspace:delete',{id});await closeDialog();}else{const name=$('#dialog-name').value.trim();if(!name)return;await invoke(type==='workspace-rename'?'workspace:rename':'workspace:add',type==='workspace-rename'?{id,name}:{name,color:agentColor(name)});await closeDialog();}}});
document.addEventListener('input',event=>{if(event.target.id==='palette-input'){paletteIndex=0;renderPalette();}else if(event.target.id==='mission-filter'){missionQuery=event.target.value;missionPage=0;renderMission();}else if(event.target.id==='page-filter'){pageQuery=event.target.value;renderPage(true);}});
document.addEventListener('change',event=>{if(event.target.matches('select[data-setting]'))invoke('settings:update',{[event.target.dataset.setting]:event.target.value});});
$('#address').addEventListener('focus',()=>{$('#address-shortcut').style.display='none';$('#address').select();});$('#address').addEventListener('blur',()=>{$('#address-shortcut').style.display='';});
async function focusAddress(){if(S.missionOpen)await invoke('ui:mission',{open:false});if(paletteOpen)await closePalette();if(dialogOpen)await closeDialog();await closeFloating();await invoke('ui:focus-chrome');$('#address').focus();$('#address').select();}
document.addEventListener('keydown',async event=>{if(event.key==='Tab'){const modal=dialogOpen?$('#dialog'):paletteOpen?$('#palette'):S.missionOpen?$('#mission'):null;if(modal){const items=$$('button:not(:disabled),input:not(:disabled),select:not(:disabled),[tabindex="0"]',modal).filter(el=>el.getClientRects().length);const first=items[0],last=items.at(-1);if(items.length&&(!modal.contains(document.activeElement)||(event.shiftKey&&document.activeElement===first)||(!event.shiftKey&&document.activeElement===last))){event.preventDefault();(event.shiftKey?last:first).focus();return;}}}if(event.key==='Escape'){if(dialogOpen)await closeDialog();else if(paletteOpen)await closePalette();else if(floating)await closeFloating();else if(S.missionOpen)await closeMission();else{$('#address').blur();await invoke('ui:focus-page');}event.preventDefault();return;}if(paletteOpen&&['ArrowDown','ArrowUp'].includes(event.key)){paletteIndex=Math.max(0,Math.min(paletteItems.length-1,paletteIndex+(event.key==='ArrowDown'?1:-1)));renderPalette();$('.palette-item.active')?.scrollIntoView({block:'nearest'});event.preventDefault();return;}const tab=event.target.closest?.('[data-tab-id]');if(tab&&event.key==='Enter'&&!event.target.closest('button')){event.preventDefault();await invoke('tab:activate',{id:tab.dataset.tabId});return;}const mission=event.target.closest?.('[data-mission-tab]');if(mission&&event.key==='Enter'&&!event.target.closest('button')){event.preventDefault();await invoke('tab:activate',{id:mission.dataset.missionTab});await closeMission();return;}if(!(event.metaKey||event.ctrlKey))return;const key=event.key.toLowerCase();if(key==='l'){event.preventDefault();focusAddress();}else if(key==='k'){event.preventDefault();await openPalette();}else if(key==='m'&&event.shiftKey){event.preventDefault();await action('mission');}else if(key==='d'){event.preventDefault();await invoke('bookmark:toggle',{});}else if(key===','){event.preventDefault();await go('aster://settings');}});
document.addEventListener('contextmenu',async event=>{const tab=event.target.closest('[data-tab-id],[data-mission-tab]');if(!tab)return;event.preventDefault();const id=tab.dataset.tabId||tab.dataset.missionTab;const request=await beginTransient('tabmenu');if(request===null)return;const item=S.tabs.find(t=>t.id===id);if(!item){await closeFloating();return;}$('#floating').classList.remove('hidden');$('#floating').innerHTML=`<button class="menu-item" data-action="pin-tab" data-id="${E(id)}">${icon('pin')}${item?.pinned?'Unpin tab':'Pin tab'}</button><button class="menu-item" data-action="mute" data-id="${E(id)}">${icon(item?.muted?'volume':'mute')}${item?.muted?'Unmute tab':'Mute tab'}</button><div class="menu-divider"></div>${S.workspaces.filter(w=>w.id!==item?.workspace).map(w=>`<button class="menu-item" data-action="move-tab" data-id="${E(id)}" data-workspace="${E(w.id)}">${icon('folder')}Move to ${E(w.name)}</button>`).join('')}<div class="menu-divider"></div><button class="menu-item" data-action="close-tab" data-id="${E(id)}">${icon('close')}Close tab<kbd>⌘W</kbd></button>`;});
const originalAction=action;
action=async function(name,data={}){if(name==='pin-tab'){await invoke('tab:pin',{id:data.id});await closeFloating();}else if(name==='move-tab'){await invoke('tab:move',{id:data.id,workspace:data.workspace});await closeFloating();}else if(name==='reload'&&activeTab()?.isLoading){await invoke('tab:stop',{});}else if(name==='find'){openFind();}else if(name==='find-next'){await invoke('page:find',{text:$('#find-text')?.value||'',next:true});}else if(name==='find-prev'){await invoke('page:find',{text:$('#find-text')?.value||'',next:true,backwards:true});}else if(name==='find-close'){closeFind();}else await originalAction(name,data);};
async function openFind(){if(internalRoute()){toast('Open a web page to find text.');return;}if(!$('#find-bar')){const bar=document.createElement('form');bar.id='find-bar';bar.className='find-bar';bar.innerHTML=`${icon('search')}<input id="find-text" aria-label="Find in page" placeholder="Find in page…" autocomplete="off"><button type="button" data-action="find-prev" title="Previous match" aria-label="Previous match">${icon('back')}</button><button type="submit" title="Next match" aria-label="Next match">${icon('forward')}</button><button type="button" data-action="find-close" title="Close find" aria-label="Close find">${icon('close')}</button>`;$('.toolbar').append(bar);bar.addEventListener('submit',e=>{e.preventDefault();invoke('page:find',{text:$('#find-text').value,next:true});});$('#find-text').addEventListener('input',()=>invoke('page:find',{text:$('#find-text').value}));$('#find-text').addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();closeFind();}});}const findBar=$('#find-bar'),findTab=S.activeTabId;await invoke('ui:focus-chrome');if($('#find-bar')!==findBar||S.activeTabId!==findTab)return;$('#find-text').focus();$('#find-text').select();}
function closeFind(restorePage=true){const bar=$('#find-bar');if(!bar)return;bar.remove();invoke('page:find',{text:''});if(restorePage)invoke('ui:focus-page');}
document.addEventListener('dragstart',event=>{const tab=event.target.closest('[data-tab-id],[data-mission-tab]');if(!tab)return;draggedTab=tab.dataset.tabId||tab.dataset.missionTab;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',draggedTab);requestAnimationFrame(()=>tab.classList.add('dragging'));});
document.addEventListener('dragover',event=>{const target=event.target.closest('[data-tab-id],[data-mission-tab],[data-drop-workspace],.space-chip[data-id]');if(!target||!draggedTab)return;event.preventDefault();event.dataTransfer.dropEffect='move';target.classList.add('drop-target');});
document.addEventListener('dragleave',event=>{const target=event.target.closest('.drop-target');if(target&&!target.contains(event.relatedTarget))target.classList.remove('drop-target');});
document.addEventListener('drop',async event=>{const target=event.target.closest('[data-tab-id],[data-mission-tab],[data-drop-workspace],.space-chip[data-id]');if(!target||!draggedTab)return;event.preventDefault();const moved=draggedTab;draggedTab=null;$$('.dragging,.drop-target').forEach(e=>e.classList.remove('dragging','drop-target'));const workspace=target.dataset.dropWorkspace||(target.classList.contains('space-chip')?target.dataset.id:null);if(workspace)await invoke('tab:move',{id:moved,workspace});else{const before=target.dataset.tabId||target.dataset.missionTab;if(before===moved)return;const ids=S.tabs.map(t=>t.id).filter(id=>id!==moved);ids.splice(ids.indexOf(before),0,moved);await invoke('tab:reorder',{ids});}});
document.addEventListener('dragend',()=>{draggedTab=null;$$('.dragging,.drop-target').forEach(e=>e.classList.remove('dragging','drop-target'));});
let wheelLock=false;$('#mission').addEventListener('wheel',event=>{if(!S.missionOpen||Math.abs(event.deltaX)<35||wheelLock)return;const {capacity}=missionGeometry(),pages=Math.max(1,Math.ceil((missionTabs().length+1)/capacity));missionPage=Math.max(0,Math.min(pages-1,missionPage+(event.deltaX>0?1:-1)));renderMission();wheelLock=true;setTimeout(()=>wheelLock=false,500);});
addEventListener('resize',()=>{if(S.missionOpen)renderMission();});matchMedia('(prefers-color-scheme:dark)').addEventListener('change',setTheme);
fillStaticIcons();
api.onState(renderState);
api.onCommand(command=>{const name=typeof command==='string'?command:command.command;const payload=typeof command==='object'?command:{};if(['focus-address','address','focusAddress'].includes(name))focusAddress();else if(['palette','command-palette'].includes(name))openPalette();else if(['mission','mission-control'].includes(name))action('mission');else if(['settings','history','bookmarks','downloads','agents'].includes(name))go('aster://'+name);else if(name==='toast')toast(payload.message||'');else if(name==='new-tab')action('new');else if(name==='find')openFind();});
api.invoke('state:get').then(renderState).catch(error=>toast(error.message));
